import type Token from "markdown-it/lib/token.mjs";
import { getMarkdown } from "@/composables/useMarkdown";

export interface OutlineItem {
  /** Heading level 1-6. */
  level: number;
  /** Plain heading label with Markdown formatting removed. */
  text: string;
  /** 1-based source line used by Monaco. */
  line: number;
  /** 0-based heading index used by Milkdown. */
  index: number;
  /** Stable preview/cross-document anchor generated by the renderer. */
  slug: string;
}

function inlineText(token: Token): string {
  if (!token.children?.length) return token.content.trim();
  return token.children
    .map((child) => {
      if (child.type === "softbreak" || child.type === "hardbreak") return " ";
      if (child.type === "image") return child.content || child.attrGet("alt") || "";
      if (child.type === "html_inline") return "";
      return child.content || "";
    })
    .join("")
    .replace(/\s+/g, " ")
    .trim();
}

/** Parse headings with the same CommonMark/GFM rules used by rendered Markdown. */
export function parseMarkdownOutline(text: string): OutlineItem[] {
  if (!text) return [];
  const out: OutlineItem[] = [];
  const tokens = getMarkdown().parse(text, {});
  for (let i = 0; i < tokens.length; i += 1) {
    const open = tokens[i];
    if (open.type !== "heading_open") continue;
    const level = Number(open.tag.slice(1));
    const inline = tokens[i + 1];
    const headingText = inline?.type === "inline" ? inlineText(inline) : "";
    if (!headingText || !Number.isInteger(level)) continue;
    out.push({
      level,
      text: headingText,
      line: (open.map?.[0] ?? 0) + 1,
      index: out.length,
      slug: String(open.meta?.textmindSlug || ""),
    });
  }
  return out;
}
